-- 0002_tables.sql — entity tables generated from schemas (P04-T02)
--
-- Expand-then-contract convention: every table is created here and
-- only removed by a later contract migration.  Each table carries
-- tenant_id, schema_version and a time-sortable primary key (id).
-- No SERIAL columns or shared sequences: identifiers are assigned
-- by the Kernel, not the database.
--
-- Generated by tools/schemagen/sqlgen.py — do not edit by hand.


CREATE TABLE IF NOT EXISTS "approval" (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    schema_version INTEGER NOT NULL,
    UNIQUE (tenant_id, id),
    justification TEXT DEFAULT NULL,
    outcome TEXT CHECK (outcome IN ('APPROVE', 'REJECT', 'OVERRIDE')),
    proposal_hash TEXT,
    reviewer_id TEXT,
    timestamp TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS "autonomy_policy" (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    schema_version INTEGER NOT NULL,
    UNIQUE (tenant_id, id),
    level TEXT CHECK (level IN ('MANUAL', 'SUPERVISED', 'AUTONOMOUS')),
    max_model_calls INTEGER DEFAULT NULL,
    max_tokens INTEGER DEFAULT NULL,
    max_tool_calls INTEGER DEFAULT NULL,
    max_wall_time_seconds INTEGER DEFAULT NULL,
    max_workflow_steps INTEGER DEFAULT NULL,
    policy_id TEXT
);

CREATE TABLE IF NOT EXISTS "case" (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    schema_version INTEGER NOT NULL,
    UNIQUE (tenant_id, id),
    created_at TIMESTAMPTZ,
    state TEXT CHECK (state IN ('CREATED', 'INGESTED', 'EXTRACTED', 'EVALUATED', 'PROPOSED', 'AWAITING_HUMAN', 'DECIDED', 'CLOSED', 'BLOCKED', 'QUARANTINED', 'FAILED', 'REOPENED')),
    version INTEGER
);

CREATE TABLE IF NOT EXISTS "decision" (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    schema_version INTEGER NOT NULL,
    UNIQUE (tenant_id, id),
    configuration_hash TEXT,
    evaluation_commitment TEXT DEFAULT NULL,
    evaluation_time TIMESTAMPTZ,
    fact_refs JSONB DEFAULT NULL,
    pack_versions JSONB DEFAULT NULL,
    reason_codes JSONB,
    rule_refs JSONB DEFAULT NULL,
    value TEXT CHECK (value IN ('ALLOW', 'ABSTAIN', 'HOLD', 'ESCALATE'))
);

CREATE TABLE IF NOT EXISTS "document" (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    schema_version INTEGER NOT NULL,
    UNIQUE (tenant_id, id),
    content_type TEXT,
    created_at TIMESTAMPTZ,
    language TEXT CHECK (language IN ('en', 'ar')),
    sha256 TEXT
);

CREATE TABLE IF NOT EXISTS "evidence_record" (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    schema_version INTEGER NOT NULL,
    UNIQUE (tenant_id, id),
    actor_id TEXT,
    actor_kind TEXT CHECK (actor_kind IN ('ROLE', 'HUMAN', 'SYSTEM')),
    alg TEXT,
    case_id TEXT,
    payload_hash TEXT,
    payload_ref TEXT DEFAULT NULL,
    prev_hash TEXT,
    record_hash TEXT,
    record_id TEXT,
    salt_id TEXT DEFAULT NULL,
    seq INTEGER,
    stage TEXT
);

CREATE TABLE IF NOT EXISTS "fact" (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    schema_version INTEGER NOT NULL,
    UNIQUE (tenant_id, id),
    confidence NUMERIC DEFAULT NULL,
    document_id TEXT DEFAULT NULL,
    extraction_method TEXT DEFAULT NULL,
    key TEXT,
    label TEXT CHECK (label IN ('OFFICIAL', 'DERIVED', 'SECONDARY', 'SIMULATED_RULE', 'SYNTHETIC', 'ASSUMPTION', 'UNVERIFIED')),
    locator TEXT DEFAULT NULL,
    source_id TEXT,
    status TEXT CHECK (status IN ('PROPOSED', 'VERIFIED', 'CONFLICTED', 'SUPERSEDED', 'REJECTED')),
    value TEXT
);

CREATE TABLE IF NOT EXISTS "memory_entry" (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    schema_version INTEGER NOT NULL,
    UNIQUE (tenant_id, id),
    entry_id TEXT,
    expiry TIMESTAMPTZ DEFAULT NULL,
    label TEXT CHECK (label IN ('OFFICIAL', 'DERIVED', 'SECONDARY', 'SIMULATED_RULE', 'SYNTHETIC', 'ASSUMPTION', 'UNVERIFIED')),
    memory_class TEXT CHECK (memory_class IN ('M0', 'M1', 'M2', 'M3', 'M4')),
    provenance TEXT DEFAULT NULL,
    retention_class TEXT,
    scope TEXT
);

CREATE TABLE IF NOT EXISTS "pack" (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    schema_version INTEGER NOT NULL,
    UNIQUE (tenant_id, id),
    jurisdiction TEXT,
    languages JSONB DEFAULT NULL,
    valid_from TIMESTAMPTZ,
    valid_to TIMESTAMPTZ,
    version TEXT
);

CREATE TABLE IF NOT EXISTS "passport" (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    schema_version INTEGER NOT NULL,
    UNIQUE (tenant_id, id),
    case_id TEXT,
    checkpoints JSONB DEFAULT NULL,
    signature TEXT
);

CREATE TABLE IF NOT EXISTS "proposal" (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    schema_version INTEGER NOT NULL,
    UNIQUE (tenant_id, id),
    evidence_refs JSONB DEFAULT NULL,
    proposal_hash TEXT,
    proposal_type TEXT
);

CREATE TABLE IF NOT EXISTS "rule_result" (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    schema_version INTEGER NOT NULL,
    UNIQUE (tenant_id, id),
    citation_locator TEXT DEFAULT NULL,
    citation_source_id TEXT DEFAULT NULL,
    evaluation_time TIMESTAMPTZ,
    reason_code TEXT,
    rule_id TEXT,
    rule_version TEXT,
    state TEXT CHECK (state IN ('APPLIED', 'NOT_APPLICABLE', 'SKIPPED'))
);

CREATE TABLE IF NOT EXISTS "simulation" (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    schema_version INTEGER NOT NULL,
    UNIQUE (tenant_id, id),
    case_id TEXT,
    parameters TEXT DEFAULT NULL,
    result TEXT DEFAULT NULL,
    sim_type TEXT CHECK (sim_type IN ('WHAT_IF', 'AS_OF'))
);

CREATE TABLE IF NOT EXISTS "source" (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    schema_version INTEGER NOT NULL,
    UNIQUE (tenant_id, id),
    dep_class TEXT CHECK (dep_class IN ('RUNTIME', 'DEV', 'TOOL', 'ACTION')),
    dep_purpose TEXT DEFAULT NULL,
    kind TEXT CHECK (kind IN ('SOURCE', 'DATASET', 'DEPENDENCY', 'STANDARD')),
    label TEXT CHECK (label IN ('OFFICIAL', 'DERIVED', 'SECONDARY', 'SIMULATED_RULE', 'SYNTHETIC', 'ASSUMPTION', 'UNVERIFIED')),
    license_summary TEXT,
    max_age_months INTEGER,
    publisher TEXT,
    redistributable TEXT CHECK (redistributable IN ('yes', 'no', 'unknown')),
    reference TEXT,
    retrieved_month TEXT,
    status TEXT CHECK (status IN ('UNVERIFIED', 'VERIFIED')),
    use_class TEXT CHECK (use_class IN ('SCREENING', 'MEASURE', 'TARIFF', 'CODELIST', 'CALENDAR', 'CATALOGUE', 'TERMS', 'SIMULATION', 'LIBRARY')),
    v_item TEXT DEFAULT NULL
);

CREATE TABLE IF NOT EXISTS "tenant" (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    schema_version INTEGER NOT NULL,
    UNIQUE (tenant_id, id),
    created_at TIMESTAMPTZ,
    name TEXT
);

-- Foreign key constraints (added after all tables exist)

